format_code:
chip esp32

hardware {
    pin led: Output = 2
}

task status {
    every 1s {
        if ble.is_connected() {
            led.on()
        } else {
            led.off()
        }
    }
}

setup {
    ble.advertise("Device")
}

system_graph.mermaid:
flowchart LR
    u_setup["setup"]
    s_ble{{"ble"}}
    u_status(("status<br>↻ 1s"))
    u_setup -->|advertise| s_ble
    s_ble -.->|is_connected| u_status
    classDef task fill:#1f3a4d,stroke:#2B7CB3,color:#e8e8e8;
    classDef timer fill:#33291a,stroke:#d0a83a,color:#f5e9cf;
    classDef machine fill:#2d1f3d,stroke:#7a3ac0,color:#e8e8e8;
    classDef func fill:#26333a,stroke:#5a8fa0,color:#e8e8e8;
